A;AAAA;AAAA;AAAA;;;;;;;;;;;;;ACAA;AAAA;AAAA;AAAA;AAAqG;AAC3B;AACL;;;AAGrE;AACsG;AACtG,gBAAgB,2GAAU;AAC1B,EAAE,4FAAM;AACR,EAAE,iGAAM;AACR,EAAE,0GAAe;AACjB;AACA;AACA;AACA;;AAEA;;AAEA;AACA,IAAI,KAAU,EAAE,YAiBf;AACD;AACe,gF;;;;;;;;;;;;ACtCf;AAAA;AAAA,wCAA8M,CAAgB,0PAAG,EAAC,C;;;;;;;;;;;;ACAlO;AAAA;AAAA;AAAA;AAAA;AAAA;;;;;;;;;;;;;ACAA;AAAA;AAAA;AAAA;AAAyG;AAC3B;AACL;;;AAGzE;AACsG;AACtG,gBAAgB,2GAAU;AAC1B,EAAE,gGAAM;AACR,EAAE,qGAAM;AACR,EAAE,8GAAe;AACjB;AACA;AACA;AACA;;AAEA;;AAEA;AACA,IAAI,KAAU,EAAE,YAiBf;AACD;AACe,gF;;;;;;;;;;;;ACtCf;AAAA;AAAA,wCAAkN,CAAgB,8PAAG,EAAC,C;;;;;;;;;;;;ACAtO;AAAA;AAAA;AAAA;AAAA;AAAA","file":"chunks/ceres-client-1.js","sourcesContent":["<template>\n    <div class=\"d-flex mb-2\">\n        <span class=\"text-muted\">{{ quantity }}x</span>\n        <div class=\"image-container mx-1\">\n            <lazy-img\n                picture-class=\"d-block mw-100 mh-100\"\n                v-if=\"itemImage\"\n                :image-url=\"itemImage\"\n                :alt=\"altText\"\n                :title=\"itemName\">\n            </lazy-img>\n        </div>\n        <div>\n            <a :href=\"variation | itemURL\" class=\"item-name text-primary text-appearance font-weight-bold text-break\">\n                {{ itemName }}\n            </a>\n            <div class=\"small\" v-for=\"attribute in variation.attributes\">\n                <strong>{{ attribute.attribute.names.name }}: </strong>\n                <span>{{ attribute.value.names.name }}</span>\n            </div>\n\n            <div class=\"text-muted small\">\n                <template v-for=\"propertyGroup in variation.variationProperties\">\n                    <div v-for=\"property in propertyGroup.properties\">\n                        <strong v-if=\"propertyGroup.name\">{{ propertyGroup.name }}: </strong>\n                        <span>{{ property.names.name }}</span>\n                        <span v-if=\"property.cast == 'file'\">\n                            <a :href=\"property.values.value | propertyFileUrl\" v-html=\"property.values.value\" target=\"_blank\"></a>\n                        </span>\n                        <span v-else v-html=\"property.values.value\"></span>\n                    </div>\n                </template>\n            </div>\n\n            <order-property-value-list :basket-item=\"mappedBasketItem\"></order-property-value-list>\n        </div>\n    </div>\n</template>\n\n<script>\nimport OrderPropertyValueList from \"../../item/OrderPropertyValueList.vue\"\n\nexport default {\n    name: \"set-component-item\",\n\n    components: {\n        OrderPropertyValueList\n    },\n    \n    props: {\n        variation: Object,\n        quantity: Number,\n        orderProperties: Array,\n        rebate: Number\n    },\n    computed: {\n        itemImage()\n        {\n            const itemImages = this.$options.filters.itemImages(this.variation.images, \"urlPreview\");\n\n            return this.$options.filters.itemImage(itemImages);\n        },\n\n        altText()\n        {\n            const images = this.$options.filters.itemImages(this.variation.images, \"urlPreview\");\n\n            return this.$options.filters.itemImageAlternativeText(images) || this.itemName;\n        },\n\n        itemName()\n        {\n            return this.$options.filters.itemName(this.variation);\n        },\n\n        mappedBasketItem()\n        {\n            // bring given data in basket item structure\n            return {\n                variation:\n                {\n                    data: this.variation\n                },\n                basketItemOrderParams: this.orderProperties\n            };\n        }\n    }\n}\n</script>","<template>\n    <div class=\"small\" v-if=\"shownProperties && shownProperties.length\">\n        <div class=\"font-weight-bold my-1\">{{ $translate('Ceres::Template.basketAdditionalCosts') }}:</div>\n        <ul class=\"ml-1 pl-3\" data-testing=\"order-property-list\">\n            <order-property-value-list-item v-for=\"property in shownProperties\" :key=\"property.propertyId\" :property=\"property\"></order-property-value-list-item>\n        </ul>\n    </div>\n</template>\n\n<script>\nimport { isDefined } from '../../helper/utils';\nimport OrderPropertyValueListItem from './OrderPropertyValueListItem.vue';\n\nexport default {\n    name: \"order-property-value-list\",\n\n    components:\n    {\n        OrderPropertyValueListItem\n    },\n\n    props:\n    {\n        basketItem:\n        {\n            required: true,\n            type: Object\n        }\n    },\n\n    computed:\n    {\n        shownProperties()\n        {\n            const shownProperties = [];\n\n            this.basketItem.variation.data.properties.forEach(property =>\n            {\n                const filledProperty = this.basketItem.basketItemOrderParams.find(prop =>\n                {\n                    return parseInt(prop.propertyId) === property.propertyId;\n                });\n\n                if (isDefined(filledProperty))\n                {\n                    if (filledProperty.type === \"selection\")\n                    {\n                        property.property.value = property.property.selectionValues[filledProperty.value].name;\n                    }\n                    else\n                    {\n                        property.property.value = filledProperty.value;\n                    }\n                }\n\n                if(isDefined(filledProperty) || this.isPropertyWithAdditionalCosts(property))\n                {\n                    shownProperties.push(property);\n                }\n            });\n\n            return shownProperties;\n        }\n    },\n\n    methods:\n    {\n        isPropertyWithAdditionalCosts(property)\n        {\n            return property.property &&\n                property.property.isShownAtCheckout &&\n                property.property.isShownAsAdditionalCosts &&\n                !property.property.isOderProperty\n        }\n    }\n}\n</script>\n","<template>\n    <li>\n        <span class=\"d-block\">\n            <strong :class=\"{ 'colon': showColon }\">\n                {{ property.property.names.name }} \n                <template v-if=\"surcharge > 0\">\n                    <template v-if=\"isAdditionalCost || isTaxless\">\n                        ({{ $translate(\"Ceres::Template.basketPlusAbbr\") }} {{ surcharge | currency }})\n                    </template>\n                    <template v-else>\n                        ({{ $translate(\"Ceres::Template.basketIncludeAbbr\") }} {{ surcharge | currency }})\n                    </template>\n                </template>\n            </strong>\n            <span>\n                <span v-if=\"property.property.valueType === 'file'\">\n                    <a :href=\"property.property.value | fileUploadPath\" target=\"_blank\">\n                        <i class=\"fa fa-external-link\" aria-hidden=\"true\"></i>\n                        {{ property.property.value | fileName }}\n                    </a>\n                </span>\n                <span v-else-if=\"property.property.valueType !== 'empty'\">{{ property.property.value }}</span>\n            </span>\n        </span>\n    </li>\n</template>\n\n<script>\nimport { hasVat, isAdditionalCosts } from \"../../helper/OrderPropertyHelper\";\nexport default {\n    name: \"order-property-value-list-item\",\n\n    props:\n    {\n        property:\n        {\n            required: true,\n            type: Object\n        }\n    },\n\n    computed:\n    {\n        surcharge()\n        {\n            return this.$options.filters.propertySurcharge([this.property], this.property.propertyId);\n        },\n\n        isAdditionalCost()\n        {\n            return isAdditionalCosts(this.property);\n        },\n\n        isTaxless()\n        {\n            return !hasVat(this.property) && App.useVariationOrderProperties;\n        },\n\n        showColon()\n        {\n            return this.property && this.property.property.value && this.property.property.valueType !== \"empty\";\n        }\n    }\n}\n</script>\n","var render = function() {\n  var _vm = this\n  var _h = _vm.$createElement\n  var _c = _vm._self._c || _h\n  return _c(\"div\", { staticClass: \"d-flex mb-2\" }, [\n    _c(\"span\", { staticClass: \"text-muted\" }, [\n      _vm._v(_vm._s(_vm.quantity) + \"x\")\n    ]),\n    _vm._v(\" \"),\n    _c(\n      \"div\",\n      { staticClass: \"image-container mx-1\" },\n      [\n        _vm.itemImage\n          ? _c(\"lazy-img\", {\n              attrs: {\n                \"picture-class\": \"d-block mw-100 mh-100\",\n                \"image-url\": _vm.itemImage,\n                alt: _vm.altText,\n                title: _vm.itemName\n              }\n            })\n          : _vm._e()\n      ],\n      1\n    ),\n    _vm._v(\" \"),\n    _c(\n      \"div\",\n      [\n        _c(\n          \"a\",\n          {\n            staticClass:\n              \"item-name text-primary text-appearance font-weight-bold text-break\",\n            attrs: { href: _vm._f(\"itemURL\")(_vm.variation) }\n          },\n          [_vm._v(\"\\n            \" + _vm._s(_vm.itemName) + \"\\n        \")]\n        ),\n        _vm._v(\" \"),\n        _vm._l(_vm.variation.attributes, function(attribute) {\n          return _c(\"div\", { staticClass: \"small\" }, [\n            _c(\"strong\", [\n              _vm._v(_vm._s(attribute.attribute.names.name) + \": \")\n            ]),\n            _vm._v(\" \"),\n            _c(\"span\", [_vm._v(_vm._s(attribute.value.names.name))])\n          ])\n        }),\n        _vm._v(\" \"),\n        _c(\n          \"div\",\n          { staticClass: \"text-muted small\" },\n          [\n            _vm._l(_vm.variation.variationProperties, function(propertyGroup) {\n              return _vm._l(propertyGroup.properties, function(property) {\n                return _c(\"div\", [\n                  propertyGroup.name\n                    ? _c(\"strong\"